let yaw=0,camPitch=.15,keys={},started=false,walk=0,joy={x:0,y:0},toastTimer;const welcome=document.querySelector('#welcome');function startGame(){started=true;welcome.classList.add('gone');document.querySelector('#hint').style.opacity=1;setTimeout(()=>{if(!isMobile)document.querySelector('#hint').style.opacity=0},8000)}document.querySelector('#start').addEventListener('click',startGame);
