488:   makeTree(x, z, s = 1) {
489:     const g = new THREE.Group(); this.scene.add(g);
490:     const trunk = std(0x332b21, 0.95);
491:     const leaf = std(0x263329, 0.95), leaf2 = std(0x303d30, 0.95);
492:     const t = new THREE.Mesh(new THREE.CylinderGeometry(0.12 * s, 0.2 * s, 2.6 * s, 6), trunk);
493:     t.position.set(x, 1.3 * s, z); t.castShadow = true; g.add(t);
494:     for (let i = 0; i < 3; i++) {
