53: .btn-ghost.danger:hover{background:rgba(168,67,47,.16);color:#f3c4b8}
54: .btn-link{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid transparent;padding-bottom:2px;transition:.2s}
