233:   makeSolidBuilding(id, loc) {
234:     const g = new THREE.Group();
235:     this.scene.add(g);
236:     const { x, z, w, d, h } = loc;
237:     const wall = std(loc.color, 0.9);
238:     const trim = std(0x6b675c, 0.9);
239:     this.makeBox(g, x, h / 2, z, w, h, d, wall);
240:     this.makeBox(g, x, h + 0.18, z, w + 0.9, 0.42, d + 0.9, std(0x262827, 0.95));
241:     this.addColliderAt(x, z, w, d, 'building');
242:     this.addWindows(x, z, w, d, h, loc.door || 'south', 0.18);
243:     const front = this.frontPos(loc);
244:     this.sign(g, loc.name.toUpperCase(), front.x, 3.5, front.z, Math.min(w * 0.72, 9), 1.15, { ry: front.ry });
245:     // awning + steps
246:     this.makeBox(g, front.x, 3.0, front.z + (front.nz || 0), Math.min(w * 0.7, 9), 0.18, 1.5, trim);
247:     this.makeBox(g, front.x, 0.12, front.z, 3.4, 0.24, 1.4, trim);
248:     return g;
249:   }
250: 
251:   addWindows(x, z, w, d, h, door, lit = 0.2) {
252:     const winMat = new THREE.MeshStandardMaterial({ color: 0x1a2021, emissive: 0xb59a63, emissiveIntensity: lit, roughness: 0.4 });
253:     this.windowMaterials.push(winMat);
254:     const floors = Math.max(1, Math.floor((h - 1.8) / 2.4));
255:     const alongFront = door === 'south' || door === 'north';
256:     const length = alongFront ? w : d;
257:     const n = Math.max(2, Math.floor(length / 3.2));
258:     for (let f = 0; f < floors; f++) {
259:       const y = 1.9 + f * 2.4;
260:       for (let i = 0; i < n; i++) {
261:         const off = (i - (n - 1) / 2) * (length / n);
262:         for (const side of [-1, 1]) {
263:           const win = new THREE.Mesh(new THREE.BoxGeometry(alongFront ? 1.05 : 0.08, 1.5, alongFront ? 0.08 : 1.05), winMat);
264:           if (alongFront) win.position.set(x + off, y, z + side * (d / 2 + 0.04));
265:           else win.position.set(x + side * (w / 2 + 0.04), y, z + off);
266:           this.scene.add(win);
267:         }
268:       }
269:     }
270:   }
271: 
272:   frontPos(loc) {
273:     const { x, z, w, d, door } = loc;
274:     if (door === 'east') return { x: x + w / 2 + 0.06, z, ry: Math.PI / 2, nz: 0 };
275:     if (door === 'west') return { x: x - w / 2 - 0.06, z, ry: -Math.PI / 2, nz: 0 };
276:     if (door === 'north') return { x, z: z - d / 2 - 0.06, ry: Math.PI, nz: 0 };
277:     return { x, z: z + d / 2 + 0.06, ry: 0, nz: 0 };
278:   }
