114: function addEvidence(world, placeId, loc, index, itemMesh) {
115:   const record = evidenceByPlace[placeId]?.[index];
116:   if (!record) return;
117:   const [suffix, label, description] = record;
118:   const id = `${placeId}:${suffix}`;
119:   if (world.interactablesById.has(id)) return;
120:   const position = new THREE.Vector3();
121:   itemMesh.getWorldPosition(position);
122:   const interactable = {
123:     id,
124:     position,
125:     label,
126:     description,
127:     kind: 'evidence',
128:     location: placeId,
129:     object: itemMesh,
130:   };
131:   world.interactables.push(interactable);
132:   world.interactablesById.set(id, interactable);
