296: function buildUndercroft(world) {
297:   const source = LOCATIONS.chapelBasement;
298:   const anchor = { ...source, x: -34, z: -34, w: 20, d: 18 };
299:   const { group, loc } = interiorGroup(world, 'chapelBasement', anchor, -3.2);
300:   box(world, loc, 0, 0.08, 0, source.w - 0.4, 0.16, source.d - 0.4, materials.stone);
301:   for (const x of [-source.w / 2, source.w / 2]) box(world, loc, x, source.h / 2, 0, 0.42, source.h, source.d, materials.darkWood);
302:   for (const z of [-source.d / 2, source.d / 2]) box(world, loc, 0, source.h / 2, z, source.w, source.h, 0.42, materials.darkWood);
303:   // Low stone piers and a ring of sockets frame the ritual mark.
304:   for (const [x, z] of [[-7, -6], [7, -6], [-7, 6], [7, 6]]) box(world, loc, x, 1.0, z, 0.9, 2.0, 0.9, materials.stone);
305:   const mark = new THREE.Mesh(new THREE.CircleGeometry(3.2, 9), materials.evidence);
306:   mark.rotation.x = -Math.PI / 2; mark.position.set(0, 0.18, 0); group.add(mark);
307:   const sockets = [];
308:   for (let i = 0; i < 9; i++) {
309:     const angle = (i / 9) * Math.PI * 2 - Math.PI / 2;
310:     const x = Math.cos(angle) * 3.8, z = Math.sin(angle) * 3.8;
311:     cylinder(world, loc, x, 0.24, z, 0.16, 0.2, 0.35, materials.stone, 8);
312:     sockets.push([x, z]);
313:   }
314:   wallSigil(world, loc, 0, 2.0, -source.d / 2 + 0.25, 2.3);
315:   evidenceProp(world, 'chapelBasement', loc, 0, -0.3, 0.25, 0, 'book');
316:   evidenceProp(world, 'chapelBasement', loc, 1, 1.15, 0.3, 0.4, 'medal');
317:   group.userData.location = 'chapelBasement';
318:   group.userData.sockets = sockets;
319:   return group;
320: }
