137:   _initRoads() {
138:     const asphalt = std(0x1b1e1e, 0.95);
139:     const sidewalk = std(0x565951, 0.94);
140:     const lineMat = std(0x8f8259, 0.7);
141:     const roadV = [-60, 0, 60], roadH = [-60, 0, 60];
142:     for (const x of roadV) {
143:       const r = new THREE.Mesh(new THREE.PlaneGeometry(11, 230), asphalt);
144:       r.rotation.x = -Math.PI / 2; r.position.set(x, 0.01, 0); r.receiveShadow = true; this.scene.add(r);
145:       for (const sx of [-7.2, 7.2]) {
146:         const s = new THREE.Mesh(new THREE.PlaneGeometry(2.6, 230), sidewalk);
147:         s.rotation.x = -Math.PI / 2; s.position.set(x + sx, 0.028, 0); s.receiveShadow = true; this.scene.add(s);
148:       }
149:       for (let z = -108; z < 108; z += 6.5) {
150:         if (roadH.some(hz => Math.abs(z - hz) < 7)) continue;
151:         const m = new THREE.Mesh(new THREE.PlaneGeometry(0.12, 2.4), lineMat);
152:         m.rotation.x = -Math.PI / 2; m.position.set(x, 0.022, z); this.scene.add(m);
153:       }
154:     }
155:     for (const z of roadH) {
156:       const r = new THREE.Mesh(new THREE.PlaneGeometry(230, 11), asphalt);
157:       r.rotation.x = -Math.PI / 2; r.position.set(0, 0.012, z); r.receiveShadow = true; this.scene.add(r);
158:       for (const sz of [-7.2, 7.2]) {
159:         const s = new THREE.Mesh(new THREE.PlaneGeometry(230, 2.6), sidewalk);
160:         s.rotation.x = -Math.PI / 2; s.position.set(0, 0.03, z + sz); s.receiveShadow = true; this.scene.add(s);
161:       }
162:       for (let x = -108; x < 108; x += 6.5) {
163:         if (roadV.some(vx => Math.abs(x - vx) < 7)) continue;
164:         const m = new THREE.Mesh(new THREE.PlaneGeometry(2.4, 0.12), lineMat);
165:         m.rotation.x = -Math.PI / 2; m.position.set(x, 0.024, z); this.scene.add(m);
166:       }
167:     }
168:     // crosswalks
169:     for (const x of roadV) for (const z of roadH) {
170:       for (let i = -3; i <= 3; i++) {
171:         for (const [dx, dz, w, h] of [[0, -6.2, 7, 0.55], [0, 6.2, 7, 0.55], [-6.2, 0, 0.55, 7], [6.2, 0, 0.55, 7]]) {
172:           const m = new THREE.Mesh(new THREE.PlaneGeometry(w - 0.5, h - 0.2), std(0x6d6a5b, 0.9));
173:           m.rotation.x = -Math.PI / 2; m.position.set(x + dx + (dx === 0 ? i * 0.9 : 0), 0.024, z + dz + (dz === 0 ? i * 0.9 : 0));
174:           this.scene.add(m);
175:         }
176:       }
177:     }
178:   }
