147: function evidenceProp(world, placeId, loc, index, x, y, z, type = 'paper') {
148:   let mesh;
149:   if (type === 'medal') {
150:     mesh = cylinder(world, loc, x, y, z, 0.2, 0.2, 0.055, materials.brass, 16);
151:     mesh.rotation.x = Math.PI / 2;
152:     cylinder(world, loc, x, y + 0.15, z, 0.035, 0.035, 0.25, materials.brass, 8);
153:   } else if (type === 'candle') {
154:     mesh = cylinder(world, loc, x, y, z, 0.09, 0.1, 0.48, materials.candle, 8);
155:     cylinder(world, loc, x, y + 0.27, z, 0.025, 0.025, 0.09, materials.evidence, 6);
156:   } else if (type === 'cup') {
157:     mesh = cylinder(world, loc, x, y, z, 0.18, 0.14, 0.28, materials.ceramic, 12);
158:   } else if (type === 'fiber') {
159:     mesh = box(world, loc, x, y, z, 0.42, 0.025, 0.035, materials.cloth, 0.4);
160:   } else {
161:     mesh = box(world, loc, x, y, z, 0.48, 0.055, 0.64, type === 'photo' ? materials.paper : materials.evidence, (index % 2 ? -0.12 : 0.08));
162:     if (type === 'book') box(world, loc, x, y + 0.045, z, 0.42, 0.025, 0.58, materials.paper, 0.03);
163:   }
164:   addEvidence(world, placeId, loc, index, mesh);
165:   return mesh;
166: }
