406:   makeCemetery() {
407:     const loc = LOCATIONS.cemetery;
408:     const g = new THREE.Group(); this.scene.add(g);
409:     const rng = rngFor(91, 'cemetery');
410:     const stone = std(0x5a5c55, 0.95), dark = std(0x3e413b, 0.95), iron = std(0x242724, 0.7, 0.4);
411:     this.makePlane(g, loc.x, 0.0, loc.z, 52, 34, std(0x2c332b, 0.98));
412:     // iron fence
413:     for (let i = 0; i < 26; i++) {
414:       const x = loc.x - 26 + i * 2.08;
415:       for (const z of [loc.z - 17, loc.z + 17]) {
416:         const post = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 1.4, 4), iron);
417:         post.position.set(x, 0.7, z); g.add(post);
418:       }
419:     }
420:     this.makeBox(g, loc.x, 1.45, loc.z - 17, 54, 0.08, 0.08, iron);
421:     this.makeBox(g, loc.x, 1.45, loc.z + 17, 54, 0.08, 0.08, iron);
422:     // graves
423:     for (let i = 0; i < 46; i++) {
424:       const gx = loc.x - 23 + (i % 11) * 4.4 + rng() * 1.1;
425:       const gz = loc.z - 12 + Math.floor(i / 11) * 6.2 + rng() * 1.2;
426:       if (Math.abs(gx - loc.x) < 4 && Math.abs(gz - loc.z) < 5) continue;
427:       const h = 0.9 + rng() * 0.6;
428:       const st = new THREE.Mesh(new THREE.BoxGeometry(0.72, h, 0.15), rng() < 0.3 ? stone : dark);
429:       st.position.set(gx, h / 2, gz); st.rotation.y = (rng() - 0.5) * 0.3; st.castShadow = true; g.add(st);
430:       if (rng() < 0.5) { const base = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.18, 0.55), stone); base.position.set(gx, 0.09, gz); g.add(base); }
431:     }
432:     // mausoleum
