466: export function buildInteriors(world) {
467:   if (!world || !world.scene || !Array.isArray(world.interactables) || world._interiorsBuilt) return;
468:   world._interiorsBuilt = true;
469:   world.interactablesById ||= new Map(world.interactables.map(item => [item.id, item]));
470:   for (const [id, build] of Object.entries(layouts)) {
471:     const loc = LOCATIONS[id];
