138: function addPortalPair(world, id, loc, fromPosition, toPosition, options = {}) {
139:   const {
140:     from = 'street',
141:     to = id,
142:     enterLabel = from === 'street' ? `Enter ${loc.short || loc.name}` : `Enter ${loc.short || loc.name}`,
143:     exitLabel = from === 'street' ? 'Exit building' : `Return to ${from}`,
144:   } = options;
145:   const source = new THREE.Vector3(...fromPosition);
146:   const destination = new THREE.Vector3(...toPosition);
147:   addInteractable(world, {
148:     id: `${id}:enter`,
149:     position: source,
150:     destinationPosition: destination.clone(),
151:     label: enterLabel,
152:     description: `${enterLabel}.`,
153:     kind: 'portal',
154:     action: 'travel',
155:     from,
156:     to,
157:     location: id,
158:   });
159:   addInteractable(world, {
160:     id: `${id}:exit`,
161:     position: destination,
162:     destinationPosition: source.clone(),
163:     label: exitLabel,
164:     description: `${exitLabel}.`,
165:     kind: 'portal',
166:     action: 'travel',
167:     from: to,
168:     to: from,
169:     location: id,
170:   });
171: }
