345:   _wall(g, x, z, w, h, d, m) {
346:     const wall = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
347:     wall.position.set(x, h / 2, z); wall.castShadow = true; wall.receiveShadow = true; g.add(wall);
348:     this.addColliderAt(x, z, w, d, 'wall');
349:     return wall;
350:   }
