251:   addWindows(x, z, w, d, h, door, lit = 0.2) {
252:     const winMat = new THREE.MeshStandardMaterial({ color: 0x1a2021, emissive: 0xb59a63, emissiveIntensity: lit, roughness: 0.4 });
253:     this.windowMaterials.push(winMat);
254:     const floors = Math.max(1, Math.floor((h - 1.8) / 2.4));
255:     const alongFront = door === 'south' || door === 'north';
256:     const length = alongFront ? w : d;
257:     const n = Math.max(2, Math.floor(length / 3.2));
258:     for (let f = 0; f < floors; f++) {
259:       const y = 1.9 + f * 2.4;
260:       for (let i = 0; i < n; i++) {
261:         const off = (i - (n - 1) / 2) * (length / n);
262:         for (const side of [-1, 1]) {
263:           const win = new THREE.Mesh(new THREE.BoxGeometry(alongFront ? 1.05 : 0.08, 1.5, alongFront ? 0.08 : 1.05), winMat);
264:           if (alongFront) win.position.set(x + off, y, z + side * (d / 2 + 0.04));
265:           else win.position.set(x + side * (w / 2 + 0.04), y, z + off);
266:           this.scene.add(win);
267:         }
268:       }
269:     }
270:   }
